d<-fread(file.path(OLD,'tables/de/M0073.tsv.gz'))[is.finite(signed_stat)&!gene%in%M20];setorder(d,-signed_stat,gene);ranks<-setNames(d$signed_stat,d$gene);h<-fread(file.path(REF,'hallmark.tsv.gz'));sets<-lapply(split(h$gene_symbol,h$gs_name),function(g)setdiff(unique(g),M20));put(data.table(model_id=paste0('V2E_',seq_along(sets)),source_model='M0073',pathway=names(sets),mask='M20',family='EC_M20_Hallmark_diagnostic',planned_n=length(sets)),'EC_M20_GSEA_registry.tsv');set.seed(123);warnings<-character();z<-withCallingHandlers(as.data.table(fgseaMultilevel(sets,ranks,minSize=15,maxSize=500,nPermSimple=10000,eps=1e-10,scoreType='std',nproc=1)),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart('muffleWarning')});budget<-10000L;if(any(grepl('overestimated|unbalanced',warnings))||any(!is.finite(z$pval))){zz<-copy(z);zz[,leadingEdge:=vapply(leadingEdge,paste,collapse=';',FUN.VALUE=character(1))];put(zz,'EC_M20_Hallmark_budget10000.tsv.gz');budget<-100000L;set.seed(123);z<-withCallingHandlers(as.data.table(fgseaMultilevel(sets,ranks,minSize=15,maxSize=500,nPermSimple=budget,eps=1e-10,scoreType='std',nproc=1)),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart('muffleWarning')})};z[,`:=`(nPermSimple=budget,numerical_warning=paste(unique(warnings),collapse=' | '),P_at_eps_floor=pval<=1e-10)];z[,leadingEdge:=vapply(leadingEdge,paste,collapse=';',FUN.VALUE=character(1))];z[,`:=`(source_model='M0073',mask='M20',FDR_family='EC_M20_Hallmark_diagnostic',q=p.adjust(pval,'BH',n=length(sets)),n_specimens=12L,n_datasets=4L,interpretation='EC own RNA shared-driver sensitivity; not Epi state grouping; not replacement for score coverage NE')];put(z,'EC_M20_Hallmark_diagnostic.tsv.gz');thread_audit('EC_masked_GSEA_complete')
